const source = items[0]?.json?.body ?? items[0]?.json ?? {};
const requiredFields = ['customerEmail', 'subject', 'message'];
const missing = requiredFields.filter((field) => !source[field]);

if (missing.length > 0) {
  return [{
    json: {
      statusCode: 400,
      response: {
        ok: false,
        error: 'Missing required fields',
        missingFields: missing
      }
    }
  }];
}

const text = [source.subject, source.message, source.plan].join(' ').toLowerCase();
let urgency = 'normal';
let routingTeam = 'general-support';
let slaHours = 24;

if (text.includes('enterprise') || text.includes('checkout') || text.includes('payment') || text.includes('outage') || text.includes('production')) {
  urgency = 'urgent';
  routingTeam = 'platform-support';
  slaHours = 2;
} else if (text.includes('billing') || text.includes('invoice') || text.includes('refund')) {
  urgency = 'high';
  routingTeam = 'billing-support';
  slaHours = 8;
}

const ticketId = 'TKT-' + Buffer.from(String(source.customerEmail) + '|' + String(source.receivedAt ?? '')).toString('hex').slice(0, 10).toUpperCase();
const summary = String(source.subject).trim() + ' - ' + String(source.message).trim().slice(0, 120);

return [{
  json: {
    statusCode: 200,
    response: {
      ok: true,
      ticketId,
      urgency,
      summary,
      routingTeam,
      slaHours,
      receivedAt: source.receivedAt ?? new Date().toISOString()
    }
  }
}];
